for check in checks:
 cmd=['ast-grep','run','--lang','python','--pattern',check['pattern'],'--json=compact',check['path']]
 p=subprocess.run(cmd,text=True,capture_output=True)
 if p.returncode not in (0,1): raise RuntimeError((check['id'],p.stderr))
 matches=json.loads(p.stdout or '[]')
 check['matches']=[dict(file=x['file'],line=x['range']['start']['line']+1,text=x['text']) for x in matches]
 if not matches:
  g=subprocess.run(['grep','-RnE',check['grep'],check['path']],text=True,capture_output=True)
  check['zero_match_grep']={'command':['grep','-RnE',check['grep'],check['path']],'returncode':g.returncode,'stdout':g.stdout}
 print(check['id'],len(matches),'; '.join(f"{x['file']}:{x['line']}" for x in check['matches'][:12]),'GREP '+check.get('zero_match_grep',{}).get('stdout','')[:500])
Path('context/changes/refactor-opportunities/verification-ast-grep.json').write_text(json.dumps({'source_commit':subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip(),'ast_grep_version':subprocess.check_output(['ast-grep','--version'],text=True).strip(),'checks':checks},indent=2)+'\n')
